<form class="card max-w-2xl space-y-5 p-6" method="post" action="<?=url('categories/save')?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($category['id'])?>"><label><span class="label">Nome da categoria</span><input class="field" name="name" value="<?=e($category['name'])?>" required></label><div class="grid gap-4 sm:grid-cols-2"><label><span class="label">Tipo</span><select class="field" name="type"><option value="fixa" <?=$category['type']==='fixa'?'selected':''?>>Fixa</option><option value="variavel" <?=$category['type']==='variavel'?'selected':''?>>Variável</option></select></label><label><span class="label">Classificação</span><select class="field" name="classification"><?php foreach(['despesa_operacional'=>'Despesa operacional','despesa_administrativa'=>'Despesa administrativa','investimento'=>'Investimento','receita_operacional'=>'Receita operacional','receita_nao_operacional'=>'Receita não operacional'] as $v=>$l):?><option value="<?=$v?>" <?=$category['classification']===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label></div><div class="flex gap-3"><button class="btn btn-primary">Salvar</button><a class="btn btn-light" href="<?=url('categories')?>">Cancelar</a></div></form>
